            hasher.combine(extraFields)
        }

        public func isEqual(to other: any ATProtocolValue) -> Bool {
            guard let other = other as? Self else { return false }
            if id != other.id {
                return false
            }
            if did != other.did {
                return false
            }
            if moderator != other.moderator {
                return false
            }
            if queue != other.queue {
                return false
            }
            if startAt != other.startAt {
                return false
            }
            if endAt != other.endAt {
                return false
            }
            return extraFields == other.extraFields
        }

        public static func == (lhs: Self, rhs: Self) -> Bool {
            return lhs.isEqual(to: rhs)
        }

        public func toCBORValue() throws -> Any {
            var map = OrderedCBORMap()
            let idValue = try id.toCBORValue()
            map = map.adding(key: "id", value: idValue)
            let didValue = try did.toCBORValue()
            map = map.adding(key: "did", value: didValue)
            if let value = moderator {
                let moderatorValue = try value.toCBORValue()
                map = map.adding(key: "moderator", value: moderatorValue)
            }
            let queueValue = try queue.toCBORValue()
            map = map.adding(key: "queue", value: queueValue)
            let startAtValue = try startAt.toCBORValue()
            map = map.adding(key: "startAt", value: startAtValue)
            if let value = endAt {
                let endAtValue = try value.toCBORValue()
                map = map.adding(key: "endAt", value: endAtValue)
            }
            return try ATProtocolValueContainer.addingExtraFields(extraFields, to: map, unlessSet: hasValue(forField:))
        }

        private static let knownFieldKeys: Swift.Set<String> = ["$type", "id", "did", "moderator", "queue", "startAt", "endAt"]

        /// Whether this value writes the wire field `name` itself. An extra field of the
        /// same name (a malformed value kept from decoding) is written only when it is not.
        private func hasValue(forField name: String) -> Bool {
            switch name {
            case "id": return true
            case "did": return true
            case "moderator": return moderator != nil
            case "queue": return true
            case "startAt": return true
            case "endAt": return endAt != nil
            default: return false
            }
        }

        private enum CodingKeys: String, CodingKey {
            case id
            case did
            case moderator
            case queue
            case startAt
            case endAt
        }
    }
}
